window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-64a3af932d8f6d2a"]={"versions": [{"id": "FIG-64a3af932d8f6d2a", "releases": ["R17-10_R1.2.0", "R18-03_R1.4.0", "R19-03", "R19-11", "R20-11", "R21-11", "R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionales Datenfluss- und Architektur-Blockdiagramm (Information Flow & Entity Diagram).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Verteilungs- und Synchronisationsmechanismus einer globalen Zeitbasis (<em>Global Time Base Distribution</em>) zwischen den Rollen <em>Time Master</em> und <em>Time Slave</em> innerhalb einer logischen <em>Time Domain</em> gemäß AUTOSAR Adaptive Platform (<code>ara::tsync</code>).</li>\n<li><strong>Architektur-Einordnung:</strong> Abbildung der Abstraktionsschichten zwischen physikalischer Hardwareuhr (<em>Time Base Reference Clock</em>), protokollspezifischer Netzwerkzeitstempelung (<em>Time Stamp</em> via HW-Capture) und dem logischen Zugriff der Applikationsschicht über das <code>ara::tsync</code>-API.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Rollen</p>\n<ul class=\"fig-list\">\n<li><strong>Time Master:</strong> Taktgebende Instanz der Domäne, die den autoritativen globalen Zeitfortschritt bestimmt und verteilt.</li>\n<li><strong>Time Slave:</strong> Taktnehmende Instanz, die ihre lokale Zeitbasis auf die empfangene Masterzeit einregelt.</li>\n</ul>\n<p class=\"fig-p\">#### Interne Entitäten & Register</p>\n<ul class=\"fig-list\">\n<li><strong>Time Base Reference Clock (Master & Slave):</strong> Physische Referenztaktquelle (z. B. freilaufender HW-Timer, POSIX-Monotonic-Clock, OS-Counter).</li>\n<li><strong>Global Time Base Raw / Local Time Base Raw:</strong></li>\n<li>Master: Roher, unkorrigierter Zeitzähler, abgeleitet direkt aus der Referenzuhr.</li>\n<li>Slave: Korrigierte Rohzeitbasis, gebildet durch Addition/Offset-Kompensation ($\\oplus$) der Taktzähler mit den Netzwerkzeitstempeln.</li>\n<li><strong>Global Time Base per Time Domain (Master, rot hervorgehoben):</strong> Domänenspezifische globale Zeit. Besitzt bidirektionalen Applikationszugriff (<strong>r/w access</strong>) zur Initialisierung, Nachführung (z. B. GNSS/PTP) oder Korrektur.</li>\n<li><strong>Local Time Base per Time Domain (Slave, rot hervorgehoben):</strong> Domänenspezifische synchronisierte Zeit. Besitzt strikten Nur-Lese-Zugriff (<strong>read access</strong>) für Applikationen.</li>\n<li><strong>Time Stamp (Tx/Rx):</strong> Sende- und Empfangszeitstempel-Einheiten, gekennzeichnet durch das Blitz-Symbol (präzises Event-/Hardware-Timestamping an MAC/PHY-Ebene).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Netzwerkbeziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>TimesyncMsg:</strong> Busgebundene Synchronisationsnachricht (z. B. IEEE 802.1AS / gPTP, CAN-TSyn, FlexRay-TimeSync).</li>\n<li><strong>Global Time Synchronized / Offset (blau hervorgehoben):</strong> Transportiertes Nutzdatenmodell (PDU/Payload mit Zeitwerten, Sequenznummern, Sub-Sekunden und Offset-Informationen).</li>\n<li><strong>r/w access (Master):</strong> Schnittstelle zur Manipulation der Masterzeitbasis (z. B. via Admin-/Master-APIs).</li>\n<li><strong>read access (Slave):</strong> Abfrageschnittstelle für Client-Applikationen (<code>ara::tsync</code>-Methoden wie <code>GetCurrentTime()</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & lokaler Basistakt:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Master und Slave initialisieren über <code>init</code> ihre jeweilige <code>Time Base Reference Clock</code>.</li>\n<li>Die Referenztaktquellen liefern kontinuierlich Inkremente (<code>update</code>) an <code>Global Time Base Raw</code> bzw. <code>Local Time Base Raw</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Master-Bereitstellung & Sende-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Global Time Base Raw</code> aktualisiert (<code>update</code>) die <code>Global Time Base per Time Domain</code>. Externe Quellen können via <code>r/w access</code> Korrekturen einsteuern.</li>\n<li>Ein Trigger stößt den Versand der <code>TimesyncMsg</code> an; die TX-Unit generiert unmittelbar beim Passieren des Schichtübergangs den Sendezeitstempel <code>Time Stamp</code> (Blitzsymbol).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenübertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Zeitinformationen werden als <code>Global Time Synchronized / Offset</code> im Protokollrahmen gekapselt übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Slave-Empfang & Offset-Regelung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beim Eintreffen der Nachricht erfasst die RX-Unit des Slaves den Empfangszeitstempel <code>Time Stamp</code> (Blitzsymbol).</li>\n<li>Differenz- und Laufzeitberechnung fließen über den Summierer/Filter ($\\oplus$) in die <code>Local Time Base Raw</code> ein.</li>\n<li><code>Local Time Base Raw</code> synchronisiert die lokale Referenz (<code>init</code>/<code>update</code>-Regelkreis zur Drift- und Frequenzkompensation / Rate Adaptation).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Slave-Bereitstellung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die gefilterte/berechnete Zeit aktualisiert (<code>update</code>) die <code>Local Time Base per Time Domain</code>.</li>\n<li>Konsumierende Slave-Applikationen greifen rein lesend über <code>read access</code> auf den synchronisierten Zeitstempel zu.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Symmetrie & Zugriffsrechte:</strong></li>\n<li>Master-Instanzen erfordern Berechtigungen für schreibende Operationen (<code>r/w access</code>), etwa zur Synchronisation gegen GNSS oder Grandmaster-Quellen.</li>\n<li>Slave-Instanzen bieten im API-Vertrag ausschließlich Leseoperationen (<code>read access</code>). Ein direktes Setzen der Domänenzeit auf Slaves ist architektonisch verboten, um Oszillationen und Domänenbrüche zu verhindern.</li>\n<li><strong>Hardware-Timestamping (Blitz-Symbol):</strong></li>\n<li>Um Jitter und Latenzen des OS-Kernels/Netzwerkstacks zu eliminieren, müssen BSP- und Treiber-Entwickler Hardware-Timestamping (SO_TIMESTAMPING, IEEE 1588 / 802.1AS PHY- oder MAC-Capture) zwingend aktivieren.</li>\n<li><strong>Entkopplung von Taktquelle und Domäne:</strong></li>\n<li>Die Trennung zwischen <code>Time Base Reference Clock</code> und <code>Time Base per Time Domain</code> ermöglicht das Multiplexing: Eine einzige physische HW-Uhr kann mehrere logische <em>Time Domains</em> mit unterschiedlichen Offsets oder Ratenkorrekturen speisen.</li>\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>Im Adaptive Platform Manifest müssen die Rollen (<code>TimeMaster</code> vs. <code>TimeSlave</code>), die Taktquellenbindung (<code>TimeBaseResource</code>), Synchronisationsintervalle und die zugehörige <code>TimeDomain</code>-ID konsistent deklariert werden.</li>\n</ul>"}, {"id": "FIG-74983a7130c601d2", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Funktionales Datenfluss- und Architektur-Blockdiagramm (Information Flow & Entity Diagram).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Verteilungs- und Synchronisationsmechanismus einer globalen Zeitbasis (<em>Global Time Base Distribution</em>) zwischen den Rollen <em>Time Master</em> und <em>Time Slave</em> innerhalb einer logischen <em>Time Domain</em> gemäß AUTOSAR Adaptive Platform (<code>ara::tsync</code>).</li>\n<li><strong>Architektur-Einordnung:</strong> Abbildung der Abstraktionsschichten zwischen physikalischer Hardwareuhr (<em>Time Base Reference Clock</em>), protokollspezifischer Netzwerkzeitstempelung (<em>Time Stamp</em> via HW-Capture) und dem logischen Zugriff der Applikationsschicht über das <code>ara::tsync</code>-API.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Rollen</p>\n<ul class=\"fig-list\">\n<li><strong>Time Master:</strong> Taktgebende Instanz der Domäne, die den autoritativen globalen Zeitfortschritt bestimmt und verteilt.</li>\n<li><strong>Time Slave:</strong> Taktnehmende Instanz, die ihre lokale Zeitbasis auf die empfangene Masterzeit einregelt.</li>\n</ul>\n<p class=\"fig-p\">#### Interne Entitäten & Register</p>\n<ul class=\"fig-list\">\n<li><strong>Time Base Reference Clock (Master & Slave):</strong> Physische Referenztaktquelle (z. B. freilaufender HW-Timer, POSIX-Monotonic-Clock, OS-Counter).</li>\n<li><strong>Global Time Base Raw / Local Time Base Raw:</strong></li>\n<li>Master: Roher, unkorrigierter Zeitzähler, abgeleitet direkt aus der Referenzuhr.</li>\n<li>Slave: Korrigierte Rohzeitbasis, gebildet durch Addition/Offset-Kompensation ($\\oplus$) der Taktzähler mit den Netzwerkzeitstempeln.</li>\n<li><strong>Global Time Base per Time Domain (Master, rot hervorgehoben):</strong> Domänenspezifische globale Zeit. Besitzt bidirektionalen Applikationszugriff (<strong>r/w access</strong>) zur Initialisierung, Nachführung (z. B. GNSS/PTP) oder Korrektur.</li>\n<li><strong>Local Time Base per Time Domain (Slave, rot hervorgehoben):</strong> Domänenspezifische synchronisierte Zeit. Besitzt strikten Nur-Lese-Zugriff (<strong>read access</strong>) für Applikationen.</li>\n<li><strong>Time Stamp (Tx/Rx):</strong> Sende- und Empfangszeitstempel-Einheiten, gekennzeichnet durch das Blitz-Symbol (präzises Event-/Hardware-Timestamping an MAC/PHY-Ebene).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Netzwerkbeziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>TimesyncMsg:</strong> Busgebundene Synchronisationsnachricht (z. B. IEEE 802.1AS / gPTP, CAN-TSyn, FlexRay-TimeSync).</li>\n<li><strong>Global Time Synchronized / Offset (blau hervorgehoben):</strong> Transportiertes Nutzdatenmodell (PDU/Payload mit Zeitwerten, Sequenznummern, Sub-Sekunden und Offset-Informationen).</li>\n<li><strong>r/w access (Master):</strong> Schnittstelle zur Manipulation der Masterzeitbasis (z. B. via Admin-/Master-APIs).</li>\n<li><strong>read access (Slave):</strong> Abfrageschnittstelle für Client-Applikationen (<code>ara::tsync</code>-Methoden wie <code>GetCurrentTime()</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & lokaler Basistakt:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Master und Slave initialisieren über <code>init</code> ihre jeweilige <code>Time Base Reference Clock</code>.</li>\n<li>Die Referenztaktquellen liefern kontinuierlich Inkremente (<code>update</code>) an <code>Global Time Base Raw</code> bzw. <code>Local Time Base Raw</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Master-Bereitstellung & Sende-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Global Time Base Raw</code> aktualisiert (<code>update</code>) die <code>Global Time Base per Time Domain</code>. Externe Quellen können via <code>r/w access</code> Korrekturen einsteuern.</li>\n<li>Ein Trigger stößt den Versand der <code>TimesyncMsg</code> an; die TX-Unit generiert unmittelbar beim Passieren des Schichtübergangs den Sendezeitstempel <code>Time Stamp</code> (Blitzsymbol).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenübertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Zeitinformationen werden als <code>Global Time Synchronized / Offset</code> im Protokollrahmen gekapselt übertragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Slave-Empfang & Offset-Regelung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beim Eintreffen der Nachricht erfasst die RX-Unit des Slaves den Empfangszeitstempel <code>Time Stamp</code> (Blitzsymbol).</li>\n<li>Differenz- und Laufzeitberechnung fließen über den Summierer/Filter ($\\oplus$) in die <code>Local Time Base Raw</code> ein.</li>\n<li><code>Local Time Base Raw</code> synchronisiert die lokale Referenz (<code>init</code>/<code>update</code>-Regelkreis zur Drift- und Frequenzkompensation / Rate Adaptation).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Slave-Bereitstellung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die gefilterte/berechnete Zeit aktualisiert (<code>update</code>) die <code>Local Time Base per Time Domain</code>.</li>\n<li>Konsumierende Slave-Applikationen greifen rein lesend über <code>read access</code> auf den synchronisierten Zeitstempel zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Symmetrie & Zugriffsrechte:</strong></li>\n<li>Master-Instanzen erfordern Berechtigungen für schreibende Operationen (<code>r/w access</code>), etwa zur Synchronisation gegen GNSS oder Grandmaster-Quellen.</li>\n<li>Slave-Instanzen bieten im API-Vertrag ausschließlich Leseoperationen (<code>read access</code>). Ein direktes Setzen der Domänenzeit auf Slaves ist architektonisch verboten, um Oszillationen und Domänenbrüche zu verhindern.</li>\n<li><strong>Hardware-Timestamping (Blitz-Symbol):</strong></li>\n<li>Um Jitter und Latenzen des OS-Kernels/Netzwerkstacks zu eliminieren, müssen BSP- und Treiber-Entwickler Hardware-Timestamping (SO_TIMESTAMPING, IEEE 1588 / 802.1AS PHY- oder MAC-Capture) zwingend aktivieren.</li>\n<li><strong>Entkopplung von Taktquelle und Domäne:</strong></li>\n<li>Die Trennung zwischen <code>Time Base Reference Clock</code> und <code>Time Base per Time Domain</code> ermöglicht das Multiplexing: Eine einzige physische HW-Uhr kann mehrere logische <em>Time Domains</em> mit unterschiedlichen Offsets oder Ratenkorrekturen speisen.</li>\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>Im Adaptive Platform Manifest müssen die Rollen (<code>TimeMaster</code> vs. <code>TimeSlave</code>), die Taktquellenbindung (<code>TimeBaseResource</code>), Synchronisationsintervalle und die zugehörige <code>TimeDomain</code>-ID konsistent deklariert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-64a3af932d8f6d2a", "to": "FIG-74983a7130c601d2", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-74983a7130c601d2", "to": "FIG-64a3af932d8f6d2a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
